using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public class TicketPredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> Scores { get; set; } = new();
}

using Microsoft.ML;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionEnginePool;
    private readonly ILogger<TicketClassifierService> _logger;

    // Labels in the order ML.NET assigns them during training
    private static readonly string[] Labels = ["Billing", "General", "Technical"];

    public TicketClassifierService(
        PredictionEnginePool<TicketData, TicketPrediction> predictionEnginePool,
        ILogger<TicketClassifierService> logger)
    {
        _predictionEnginePool = predictionEnginePool;
        _logger = logger;
    }

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEnginePool.Predict(ticketData);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < Labels.Length && i < prediction.Score.Length; i++)
        {
            scores[Labels[i]] = prediction.Score[i];
        }

        _logger.LogInformation(
            "Predicted category {Category} for ticket '{Subject}'",
            prediction.Category, request.Subject);

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Scores = scores
        };
    }

    /// <summary>
    /// Trains the model, evaluates it, saves to disk, and returns metrics.
    /// Called once at startup.
    /// </summary>
    public static Dictionary<string, object> TrainAndSave(string dataPath, string modelPath, ILogger logger)
    {
        var mlContext = new MLContext(seed: 42);

        var data = mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        // Combine text features and numeric priority into a single feature vector
        var pipeline = mlContext.Transforms.Text
                .FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        logger.LogInformation("Training model from {DataPath}...", dataPath);
        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

        logger.LogInformation("--- Evaluation Metrics ---");
        logger.LogInformation("MacroAccuracy:    {MacroAccuracy:F4}", metrics.MacroAccuracy);
        logger.LogInformation("MicroAccuracy:    {MicroAccuracy:F4}", metrics.MicroAccuracy);
        logger.LogInformation("LogLoss:          {LogLoss:F4}", metrics.LogLoss);
        logger.LogInformation("LogLossReduction: {LogLossReduction:F4}", metrics.LogLossReduction);

        mlContext.Model.Save(model, split.TrainSet.Schema, modelPath);
        logger.LogInformation("Model saved to {ModelPath}", modelPath);

        return new Dictionary<string, object>
        {
            ["MacroAccuracy"] = metrics.MacroAccuracy,
            ["MicroAccuracy"] = metrics.MicroAccuracy,
            ["LogLoss"] = metrics.LogLoss,
            ["LogLossReduction"] = metrics.LogLossReduction
        };
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketsController : ControllerBase
{
    private readonly TicketClassifierService _classifierService;

    public TicketsController(TicketClassifierService classifierService)
    {
        _classifierService = classifierService;
    }

    [HttpPost("classify")]
    public ActionResult<TicketPredictionResponse> Classify([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject and Description are required.");

        if (request.Priority is < 1 or > 3)
            return BadRequest("Priority must be between 1 and 3.");

        var prediction = _classifierService.Predict(request);
        return Ok(prediction);
    }
}

