using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup and register the pooled prediction engine
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

var startupLogger = LoggerFactory.Create(b => b.AddConsole()).CreateLogger("Startup");
var trainingMetrics = TicketClassifierService.TrainAndSave(dataPath, modelPath, startupLogger);

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath);
builder.Services.AddSingleton(trainingMetrics);
builder.Services.AddTransient<TicketClassifierService>();

var app = builder.Build();
app.MapControllers();

// Expose training metrics at GET /api/metrics
app.MapGet("/api/metrics", (Dictionary<string, object> metrics) => Results.Ok(metrics));

app.Run();

